            reason: `Security Policy Violation: Path '${targetPath}' matches protected pattern '${pattern}'`,
          };
        }
      } else if (patLower.endsWith("*")) {
        const prefix = patLower.slice(0, -1);
        if (segments.some((seg) => seg.toLowerCase().startsWith(prefix))) {
          return {
            protected: true,
            reason: `Security Policy Violation: Path '${targetPath}' matches protected pattern '${pattern}'`,
          };
        }
      } else {
